def house_bowling(rolls: list[int]) -> int:
    def at(idx: int) -> int:
        return rolls[idx] if idx < len(rolls) else 0

    total = 0
    i = 0
    for _ in range(9):
        if rolls[i] == 10:
            total += 10 + at(i + 1) + at(i + 2)
            i += 1
        else:
            frame = rolls[i] + at(i + 1)
            if frame == 10:
                total += 10 + at(i + 2)
            else:
                total += frame
            i += 2
    total += sum(rolls[i:])
    return total
